import { createHash } from 'node:crypto'
import { z } from 'zod'
import type { AppHash, SpecHash, SpecId } from '../spec/index.js'
import type { GeneratedStamp } from './records.js'

/**
 * Sole owner of the generated-file header format. Written by `writeGenerated`, read by
 * `staleness`, the reporter, and `fix`.
 *
 *   // GENERATED by libretto from specs/auth/login.md (hash: 9f2c1a…)
 *   // DO NOT EDIT. Edit the spec and run `libretto generate`.
 *   // libretto: {"spec":"auth/login","specHash":"9f2c…","appHash":"c0de…","bodyHash":"41ab…"}
 *
 * Lines 1–2 are SPEC's human header. Line 3 is the machine stamp. `bodyHash` covers
 * everything after the header, so a hand edit is detectable without a second manifest.
 * `appHash` is `app.md` at generation time, so an `app.md` edit is visible per file.
 */
export interface Header extends GeneratedStamp {
  readonly spec: SpecId
}

export function sha256(text: string): string {
  return createHash('sha256').update(text).digest('hex')
}

const MACHINE_PREFIX = '// libretto: '

const stampSchema = z.object({
  spec: z.string(),
  specHash: z.string(),
  appHash: z.string(),
  bodyHash: z.string(),
})

/** Returns the whole file text: the three header lines followed by `body` unchanged. */
export function renderHeader(spec: SpecId, specFile: string, specHash: SpecHash, appHash: AppHash, body: string): string {
  const machine = { spec, specHash, appHash, bodyHash: sha256(body) }
  return [
    `// GENERATED by libretto from ${specFile} (hash: ${specHash.slice(0, 6)}\u2026)`,
    '// DO NOT EDIT. Edit the spec and run `libretto generate`.',
    `${MACHINE_PREFIX}${JSON.stringify(machine)}`,
    body,
  ].join('\n')
}

/** `null` if the file has no valid header (treated as hand-written: `generate` overwrites with a warning). */
export function parseHeader(fileText: string): { header: Header; body: string } | null {
  const first = fileText.indexOf('\n')
  const second = first < 0 ? -1 : fileText.indexOf('\n', first + 1)
  const third = second < 0 ? -1 : fileText.indexOf('\n', second + 1)
  if (third < 0) return null
  if (!fileText.startsWith('// GENERATED by libretto')) return null
  const machine = fileText.slice(second + 1, third)
  if (!machine.startsWith(MACHINE_PREFIX)) return null
  let json: unknown
  try {
    json = JSON.parse(machine.slice(MACHINE_PREFIX.length))
  } catch {
    return null
  }
  const parsed = stampSchema.safeParse(json)
  if (!parsed.success) return null
  return {
    header: {
      spec: parsed.data.spec as SpecId,
      specHash: parsed.data.specHash as SpecHash,
      appHash: parsed.data.appHash as AppHash,
      bodyHash: parsed.data.bodyHash,
    },
    body: fileText.slice(third + 1),
  }
}
